def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]
    last_my = my[-1]
    last_opp = opp[-1]

    if n == 2:
        return 'D' if last_opp == 'D' and last_my == 'C' else 'C'

    total_opp_def = opp.count('D')
    total_my_def = my.count('D')

    if total_opp_def == n:
        return 'D'

    if total_opp_def == 0:
        if n >= 96:
            return 'D'
        return 'C'

    if n >= 96:
        return 'D'

    window = 8 if n >= 8 else n
    recent_opp = opp[-window:]
    recent_my = my[-window:]
    opp_recent_def = recent_opp.count('D')
    my_recent_def = recent_my.count('D')

    if n >= 25 and opp_recent_def == 0 and total_opp_def <= max(1, n // 20):
        if n % 19 == 0:
            return 'D'
        return 'C'

    opp_after_my_c_tot = 0
    opp_after_my_c_def = 0
    opp_after_my_d_tot = 0
    opp_after_my_d_def = 0

    for i in range(n - 1):
        if my[i] == 'C':
            opp_after_my_c_tot += 1
            if opp[i + 1] == 'D':
                opp_after_my_c_def += 1
        else:
            opp_after_my_d_tot += 1
            if opp[i + 1] == 'D':
                opp_after_my_d_def += 1

    p_def_after_c = opp_after_my_c_def / opp_after_my_c_tot if opp_after_my_c_tot > 0 else 0.0
    p_def_after_d = opp_after_my_d_def / opp_after_my_d_tot if opp_after_my_d_tot > 0 else 0.0

    if n >= 12:
        if p_def_after_d > p_def_after_c + 0.25:
            if last_opp == 'D':
                return 'D'
            return 'C'
        if n >= 20 and p_def_after_c > p_def_after_d + 0.30:
            if last_opp == 'C' and total_opp_def >= 1:
                return 'D'
            if last_opp == 'D':
                return 'D'

    if n >= 12 and opp_recent_def >= 5:
        if opp_recent_def >= 7 or last_opp == 'D':
            return 'D'
        return 'C'

    if last_opp == 'D':
        if n >= 4 and opp[-2] == 'D' and opp[-3] == 'D':
            if n >= 6 and opp[-4] == 'D':
                return 'C'
            return 'D'
        if total_opp_def * 5 <= n and my_recent_def <= 2:
            if rng.random() < 0.5:
                return 'C'
        if total_opp_def * 3 >= n * 2:
            return 'D'
        if opp_recent_def >= 3:
            return 'D'
        return 'C'

    if n > 15 and opp_recent_def <= 1:
        if rng.random() < 0.10 and (n - 1) % 7 != 0:
            return 'D'
        return 'C'

    if n > 10 and total_opp_def == 1 and total_my_def >= 1:
        return 'D'

    return 'C'
